"""Corpus labeling client: submit raw txs to a stock daemon oracle over RPC.

Reads the credential file at runtime (never writes it anywhere). Uses only
the allowed RPC set: get_info, send_raw_transaction (do_not_relay=true),
get_transaction_pool, flush_txpool. Stays under the daemon's rate limit with
a fixed inter-request delay.

The RPC endpoint and the credential file are REQUIRED command-line options;
there are no defaults.

The credential file is a plain text file of "key: value" lines; it must
define at least the keys "user" and "password" (the RPC digest credentials).

Usage:
  label_oracle.py --endpoint HOST:PORT --credential-file PATH smoke
  label_oracle.py --endpoint HOST:PORT --credential-file PATH label <jsonl> <out.json>
  label_oracle.py --endpoint HOST:PORT --credential-file PATH label-mut <jsonl> <outdir> <n>
"""
import argparse
import hashlib
import json
import os
import random
import sys
import time
import urllib.request
import urllib.parse

CRED = None
DELAY = 0.13  # ~7.7 req/s, under a typical 20/s daemon limit and ~10/s guidance
_label_cache = None
_CONN = None
_HOST = None
_PORT = None


def parse_endpoint(s):
    """'HOST:PORT' -> (host, port); usage error with a one-line explanation
    if malformed."""
    host, sep, port = s.rpartition(":")
    if not sep or not host or not port.isdigit():
        raise SystemExit("error: endpoint must be HOST:PORT (pass --endpoint HOST:PORT)")
    return host, int(port)


def creds():
    global _label_cache
    if CRED is None:
        raise SystemExit("error: no credential file configured (pass --credential-file PATH)")
    if _label_cache is None:
        d = {}
        for line in open(CRED):
            if ":" in line:
                k, v = line.strip().split(":", 1)
                d[k.strip()] = v.strip()
        _label_cache = (d["user"], d["password"])
    return _label_cache


class OracleConn:
    """Persistent-connection digest auth (monerod/epee nonce is per TCP
    connection: the authenticated request must reuse the connection that got
    the 401, with nc incrementing)."""

    def __init__(self, host, port, path="/json_rpc"):
        self.host, self.port, self.path = host, port, path
        self.conn = None
        self.nonce = None
        self.nc = 0
        self.realm = "monero-rpc"
        user, pw = creds()
        self.user, self.pw = user, pw

    def _connect(self):
        import http.client
        self.conn = http.client.HTTPConnection(self.host, self.port, timeout=30)
        body = b'{"jsonrpc":"2.0","id":"0","method":"get_info"}'
        self.conn.request("POST", self.path, body=body,
                          headers={"Content-Type": "application/json"})
        resp = self.conn.getresponse()
        resp.read()
        if resp.status != 401:
            raise RuntimeError(f"expected 401 challenge, got {resp.status}")
        ch = resp.getheader("WWW-Authenticate")
        import re
        self.nonce = re.search(r'nonce="([^"]+)"', ch).group(1)
        self.realm = re.search(r'realm="([^"]+)"', ch).group(1)
        self.nc = 0

    def _auth_header(self, path):
        import hashlib
        def md5(x):
            return hashlib.md5(x.encode()).hexdigest()
        ha1 = md5(f"{self.user}:{self.realm}:{self.pw}")
        ha2 = md5(f"POST:{path}")
        self.nc += 1
        cnonce = hashlib.md5(str(self.nc).encode()).hexdigest()[:16]
        response = md5(f"{ha1}:{self.nonce}:{self.nc:08x}:{cnonce}:auth:{ha2}")
        return (f'Digest username="{self.user}", realm="{self.realm}", '
                f'nonce="{self.nonce}", uri="{path}", algorithm=MD5, '
                f'response="{response}", qop=auth, nc={self.nc:08x}, cnonce="{cnonce}"')

    def rpc(self, method, params=None, delay=DELAY):
        import http.client, json as _json
        if self.conn is None:
            self._connect()
        body = _json.dumps({"jsonrpc": "2.0", "id": "0", "method": method,
                            "params": params or {}}).encode()
        try:
            self.conn.request("POST", self.path, body=body, headers={
                "Content-Type": "application/json",
                "Authorization": self._auth_header(self.path)})
            resp = self.conn.getresponse()
            data = resp.read()
        except (http.client.HTTPException, OSError):
            self.conn = None
            raise
        time.sleep(delay)
        if resp.status == 401:
            self.conn.close()
            self.conn = None
            raise RuntimeError("401 after auth — nonce/connection lost")
        return _json.loads(data)


    def uri(self, path, params):
        """POST a JSON request to an epee URI endpoint on the same authenticated
        connection (send_raw_transaction lives here, not in /json_rpc; epee URI
        handlers take a plain JSON object, no jsonrpc envelope, and answer with
        {'status': 'OK'} or an error field)."""
        import json as _json
        return self._post_form(path, _json.dumps(params).encode())

    def _post_form(self, path, body):
        import http.client, json as _json, urllib.parse as _up
        if self.conn is None:
            self._connect()
        try:
            self.conn.request("POST", path, body=body, headers={
                "Content-Type": "application/json",
                "Authorization": self._auth_header(path)})
            resp = self.conn.getresponse()
            data = resp.read()
        except (http.client.HTTPException, OSError):
            self.conn = None
            raise
        time.sleep(DELAY)
        if resp.status == 401:
            self.conn.close()
            self.conn = None
            raise RuntimeError("401 after auth")
        if not data:
            # epee sometimes returns 200 with an empty body on a reused
            # connection: retry once on a fresh connection
            self.conn.close()
            self.conn = None
            self._connect()
            try:
                self.conn.request("POST", path, body=body, headers={
                    "Content-Type": "application/json",
                    "Authorization": self._auth_header(path)})
                resp = self.conn.getresponse()
                data = resp.read()
            except (http.client.HTTPException, OSError):
                self.conn = None
                raise
            time.sleep(DELAY)
        return _json.loads(data if data else b'{"status":"EMPTY"}')


def set_endpoint(host, port):
    """Configure the daemon endpoint used by the module-level helpers."""
    global _HOST, _PORT
    _HOST, _PORT = host, port


def _conn():
    global _CONN
    if _CONN is None:
        if _HOST is None or _PORT is None:
            raise SystemExit("error: no endpoint configured (pass --endpoint HOST:PORT)")
        _CONN = OracleConn(_HOST, _PORT)
    return _CONN


def label_tx_conn(conn, tx_hex: str):
    """accept | reject:<reason-class>, on a given OracleConn (any endpoint)."""
    out = conn.uri("/send_raw_transaction", {"tx_as_hex": tx_hex, "do_not_relay": True})
    if "Method not found" in str(out.get("error", "")):
        raise SystemExit("FATAL: endpoint wrong — labels invalid, aborting")
    if out.get("status") == "OK" and "error" not in out:
        return "accept", ""
    for flag in ("invalid_input", "fee_too_low", "double_spend", "invalid_output",
                 "low_mixin", "overspend", "too_big", "sanity_check_failed",
                 "nonzero_unlock_time", "too_few_outputs", "tx_extra_too_big"):
        if out.get(flag):
            return "reject", flag
    msg = str(out.get("error", out.get("reason", ""))).lower()
    if "double spend" in msg or "key image" in msg:
        cls = "key-image-spent"
    elif "fee" in msg:
        cls = "fee"
    elif "parse" in msg or "deserial" in msg or "invalid" in msg:
        cls = "parse"
    else:
        cls = "verify"
    return "reject", cls


def rpc(method, params=None):
    return _conn().rpc(method, params)


def uri(path, form):
    return _conn().uri(path, form)


def label_tx(tx_hex: str):
    """accept | reject:<reason-class>"""
    out = uri("/send_raw_transaction", {"tx_as_hex": tx_hex, "do_not_relay": True})
    if "Method not found" in str(out.get("error", "")):
        raise SystemExit("FATAL: endpoint wrong — labels invalid, aborting")
    if out.get("status") == "OK" and "error" not in out:
        return "accept", ""
    for flag in ("invalid_input", "fee_too_low", "double_spend", "invalid_output",
                 "low_mixin", "overspend", "too_big", "sanity_check_failed",
                 "nonzero_unlock_time", "too_few_outputs", "tx_extra_too_big"):
        if out.get(flag):
            return "reject", flag
    msg = str(out.get("error", out.get("reason", ""))).lower()
    if "double spend" in msg or "key image" in msg:
        cls = "key-image-spent"
    elif "fee" in msg:
        cls = "fee"
    elif "parse" in msg or "deserial" in msg or "invalid" in msg:
        cls = "parse"
    else:
        cls = "verify"
    return "reject", cls


def pool_flush():
    rpc("flush_txpool", {"txids": []})


def main():
    ap = argparse.ArgumentParser(
        description="Corpus labeling client (digest-auth RPC oracle client).")
    ap.add_argument("--endpoint", required=True, metavar="HOST:PORT",
                    help="stock-daemon RPC endpoint (required, no default)")
    ap.add_argument("--credential-file", required=True, metavar="PATH",
                    help='text file of "key: value" lines with "user" and '
                         '"password" keys (required, no default)')
    ap.add_argument("mode", help="smoke | label | label-mut")
    ap.add_argument("args", nargs="*", metavar="ARG",
                    help="mode arguments: label <jsonl> <out.json> | "
                         "label-mut <jsonl> <outdir> <n>")
    a = ap.parse_args()
    host, port = parse_endpoint(a.endpoint)
    set_endpoint(host, port)
    global CRED
    CRED = a.credential_file

    mode = a.mode
    if mode == "smoke":
        if len(a.args) != 0:
            ap.error("smoke takes no positional arguments")
        out = rpc("get_info")
        r = out.get("result", {})
        print("height:", r.get("height"), "offline:", r.get("offline"),
              " synchronized:", r.get("synchronized"))
    elif mode == "label":
        if len(a.args) != 2:
            ap.error("label requires: label <jsonl> <out.json>")
        jsonl, out_json = a.args
        results = []
        for line in open(jsonl):
            rec = json.loads(line)
            lab, cls = label_tx(rec["as_hex"])
            results.append({"tx_hash": rec.get("tx_hash"),
                            "height": rec.get("height"),
                            "label": lab, "class": cls})
            print(rec.get("height"), rec.get("tx_hash", "")[:10], lab, cls)
            if lab == "accept":
                pool_flush()  # keep the pool clean for the next case
        json.dump(results, open(out_json, "w"), indent=1)
    elif mode == "label-mut":
        if len(a.args) != 3:
            ap.error("label-mut requires: label-mut <jsonl> <outdir> <n>")
        jsonl, outdir, n = a.args[0], a.args[1], int(a.args[2])
        rng = random.Random(0x6D6F6E65746F)
        parents = [json.loads(l) for l in open(jsonl)]
        os.makedirs(outdir, exist_ok=True)
        cases = []
        i = 0
        import os as _os
        while i < n:
            cid = f"mut{i:05d}"
            if _os.path.exists(os.path.join(outdir, cid + ".hex")):
                i += 1
                continue
            p = parents[i % len(parents)]
            h = bytes.fromhex(p["as_hex"])
            pos = rng.randrange(len(h))
            m = bytearray(h)
            m[pos] ^= 1 << rng.randrange(8)
            for attempt in range(3):
                try:
                    lab, cls = label_tx(m.hex())
                    break
                except (RuntimeError, OSError):
                    if attempt == 2:
                        raise
                    time.sleep(1.0)
            cid = f"mut{i:05d}"
            blob = bytes(m)
            open(os.path.join(outdir, cid + ".hex"), "w").write(blob.hex())
            cases.append({"id": cid, "parent": p["tx_hash"], "parent_height": p["height"],
                          "mutation": f"byteflip@{pos}", "label": lab, "class": cls,
                          "sha256": hashlib.sha256(blob).hexdigest()})
            print(cid, lab, cls)
            if lab == "accept":
                pool_flush()
            i += 1
        json.dump(cases, open(os.path.join(outdir, "labels.json"), "w"), indent=1)
    else:
        ap.error("mode must be one of: smoke, label, label-mut")


if __name__ == "__main__":
    main()
